import{_ as a,o as e,c as o,a2 as d}from"./chunks/framework.DDY-poMm.js";const g=JSON.parse('{"title":"站点配置","description":"","frontmatter":{},"headers":[],"relativePath":"zh/guide/site-config.md","filePath":"zh/guide/site-config.md","lastUpdated":1790683574000}'),r={name:"zh/guide/site-config.md"};function s(i,t,c,n,l,p){return e(),o("div",null,[...t[0]||(t[0]=[d('<h1 id="站点配置" tabindex="-1">站点配置 <a class="header-anchor" href="#站点配置" aria-label="Permalink to &quot;站点配置&quot;">​</a></h1><p>用户端看到的菜单、图标、首页币种、VIP 等级等，<strong>绝大部分不写死在代码里</strong>，而是由运营在后台的「基础配置」中调整。改完保存，用户端重新打开即生效，不需要技术介入、不需要重新发版。</p><p>本页先逐项说明「基础配置」下的各个标签页，末尾再说明「第三方配置」页里的八张接入卡片。</p><h2 id="侧边栏配置" tabindex="-1">侧边栏配置 <a class="header-anchor" href="#侧边栏配置" aria-label="Permalink to &quot;侧边栏配置&quot;">​</a></h2><p>用户端「我的」页面里的功能入口列表。可配置每一项的名称、图标、跳转地址、排序与开关。</p><p>关掉某一项，用户端就不再显示该入口。</p><div class="danger custom-block"><p class="custom-block-title">这里的 key 决定 App 打开哪个页面</p><p>每一项都有一个 <strong>key</strong>。App 是<strong>靠 key 来决定用哪个原生页面</strong>的 —— key 填对了，点进去是流畅的原生页； <strong>key 填错或没配这一项，App 里就直接没有这个入口</strong>。</p><p>已实现原生页的常用 key（填错 App 认不出来）：</p><table tabindex="0"><thead><tr><th>key</th><th>对应功能</th></tr></thead><tbody><tr><td><code>service</code></td><td><strong>在线客服</strong>（详见<a href="/CoinExchange/zh/guide/customer-service">在线客服</a>）</td></tr><tr><td><code>helper</code></td><td>帮助中心</td></tr><tr><td><code>language</code></td><td>多语言</td></tr><tr><td><code>primary</code> / <code>advanced</code></td><td>初级认证 / 实名认证</td></tr><tr><td><code>certified</code></td><td>邮箱认证</td></tr><tr><td><code>bank</code></td><td>绑定银行卡</td></tr><tr><td><code>tardPwd</code> / <code>loginPwd</code></td><td>资金密码 / 登录密码</td></tr><tr><td><code>termsService</code></td><td>服务条款</td></tr><tr><td><code>paper</code></td><td>白皮书</td></tr></tbody></table><p><strong>如果 App 里找不到某个功能入口，先来这里确认对应的 key 有没有配、有没有开</strong>， 这比怀疑 App 出问题要快得多。</p></div><div class="tip custom-block"><p class="custom-block-title">首页金刚区同理</p><p>「金刚区」的 key 规则与这里一致（如 <code>financial</code> 理财、<code>pledge</code> 质押、<code>subscription</code> 申购、 <code>download_center</code> 下载中心、<code>promotion_center</code> 推广中心）。</p></div><h2 id="底部栏设置" tabindex="-1">底部栏设置 <a class="header-anchor" href="#底部栏设置" aria-label="Permalink to &quot;底部栏设置&quot;">​</a></h2><p>用户端底部导航栏（首页 / 行情 / 交易 / 资产 等）。可配置名称、选中与未选中的图标、跳转地址、排序与开关。</p><div class="warning custom-block"><p class="custom-block-title">注意</p><p>底部栏是用户端的骨架。<strong>至少保留首页与资产</strong>，全部关闭会让用户无法导航。</p></div><h2 id="金刚区" tabindex="-1">金刚区 <a class="header-anchor" href="#金刚区" aria-label="Permalink to &quot;金刚区&quot;">​</a></h2><p>首页顶部的宫格快捷入口区。配置项与侧边栏一致。</p><h2 id="首页币种设置" tabindex="-1">首页币种设置 <a class="header-anchor" href="#首页币种设置" aria-label="Permalink to &quot;首页币种设置&quot;">​</a></h2><p>首页行情列表默认展示哪些币种、以什么顺序展示。</p><h2 id="资产-tab-设置" tabindex="-1">资产 Tab 设置 <a class="header-anchor" href="#资产-tab-设置" aria-label="Permalink to &quot;资产 Tab 设置&quot;">​</a></h2><p>用户资产页的分区标签（如现货资产、合约资产、理财资产等）。关掉某一个，资产页就不再显示该分区。</p><h2 id="玩法配置" tabindex="-1">玩法配置 <a class="header-anchor" href="#玩法配置" aria-label="Permalink to &quot;玩法配置&quot;">​</a></h2><p>各交易玩法的总开关。关掉某一项，用户端对应入口即隐藏。</p><h2 id="平台-logo-设置" tabindex="-1">平台 logo 设置 <a class="header-anchor" href="#平台-logo-设置" aria-label="Permalink to &quot;平台 logo 设置&quot;">​</a></h2><p>平台 Logo 及各尺寸图标（57×57 / 72×72 / 120×120 / 144×144）。</p><h2 id="vip-等级设置-vip-说明" tabindex="-1">VIP 等级设置 / VIP 说明 <a class="header-anchor" href="#vip-等级设置-vip-说明" aria-label="Permalink to &quot;VIP 等级设置 / VIP 说明&quot;">​</a></h2><ul><li><strong>VIP 等级设置</strong>：各等级的门槛</li><li><strong>VIP 说明</strong>：展示给用户看的等级权益说明文案</li></ul><h2 id="下载地址配置" tabindex="-1">下载地址配置 <a class="header-anchor" href="#下载地址配置" aria-label="Permalink to &quot;下载地址配置&quot;">​</a></h2><p>用户端「下载中心」里展示的下载入口列表，每一项含名称、下载地址、排序与开关。</p><div class="tip custom-block"><p class="custom-block-title">与 App 自动更新的区别</p><p>下载中心是<strong>给新用户装 App 用的</strong>；已经装了 App 的老用户走的是自动更新，配置在「App版本更新」里。两者互不影响，但建议保持指向同一个版本。</p></div><h2 id="app-版本更新" tabindex="-1">App 版本更新 <a class="header-anchor" href="#app-版本更新" aria-label="Permalink to &quot;App 版本更新&quot;">​</a></h2><p>控制已安装 App 的用户是否收到新版本提示。<strong>这是超级管理员专属配置</strong>，详见 <a href="/CoinExchange/zh/guide/app-release">App 版本发布</a>。</p><h2 id="登录注册配置" tabindex="-1">登录注册配置 <a class="header-anchor" href="#登录注册配置" aria-label="Permalink to &quot;登录注册配置&quot;">​</a></h2><p>控制用户可以用哪些方式注册与登录（邮箱 / 手机 / 普通 / 钱包地址），以及新用户的初始信用分。</p><h2 id="验证码设置-时区设置" tabindex="-1">验证码设置 / 时区设置 <a class="header-anchor" href="#验证码设置-时区设置" aria-label="Permalink to &quot;验证码设置 / 时区设置&quot;">​</a></h2><ul><li><strong>验证码设置</strong>：图形验证码的相关配置</li><li><strong>时区设置</strong>：平台的时区基准，影响后台与用户端的时间显示</li></ul><h2 id="白皮书配置" tabindex="-1">白皮书配置 <a class="header-anchor" href="#白皮书配置" aria-label="Permalink to &quot;白皮书配置&quot;">​</a></h2><p>平台白皮书文件地址。</p><div class="warning custom-block"><p class="custom-block-title">提示</p><p>建议放<strong>网页或 PDF</strong>。如果配成 <code>.doc</code> 文件，用户端可能无法直接预览。</p></div><h2 id="提示音配置" tabindex="-1">提示音配置 <a class="header-anchor" href="#提示音配置" aria-label="Permalink to &quot;提示音配置&quot;">​</a></h2><p>后台收到充值 / 提现事件时的提示音。</p><h2 id="后台-ip-控制" tabindex="-1">后台 IP 控制 <a class="header-anchor" href="#后台-ip-控制" aria-label="Permalink to &quot;后台 IP 控制&quot;">​</a></h2><p>限制哪些 IP 可以访问运营后台。<strong>超级管理员专属配置</strong>。</p><div class="danger custom-block"><p class="custom-block-title">高风险操作</p><p>配置错误会把自己也挡在后台之外。修改前请确认当前使用的出口 IP 已在白名单内。</p></div><h2 id="打码配置" tabindex="-1">打码配置 <a class="header-anchor" href="#打码配置" aria-label="Permalink to &quot;打码配置&quot;">​</a></h2><p>各业务模块的打码（数据脱敏）开关，含总开关与各玩法子开关。</p><hr><h2 id="第三方配置" tabindex="-1">第三方配置 <a class="header-anchor" href="#第三方配置" aria-label="Permalink to &quot;第三方配置&quot;">​</a></h2><p>与「基础配置」是两个不同的页面。这一页集中放<strong>平台与外部服务的接入信息</strong>，改动频率低、但改错影响面大，建议由超级管理员或指定的一位运营负责。</p><table tabindex="0"><thead><tr><th>卡片</th><th>是什么</th><th>谁能改</th></tr></thead><tbody><tr><td>短信配置</td><td>短信服务商的账号、密码与请求地址，用于手机验证码</td><td>有配置权限的运营</td></tr><tr><td>邮箱配置</td><td>发信邮箱的账号、密码、服务器地址与端口，用于邮件验证码与通知</td><td>有配置权限的运营</td></tr><tr><td>OSS 配置</td><td>对象存储（图片、附件）的域名、账号与存储桶，用户上传的头像、实名资料、客服图片都存在这里</td><td>有配置权限的运营</td></tr><tr><td>TG 机器人</td><td><strong>充值 / 提现告警机器人</strong>，把充提事件推送到运营的 Telegram 群。群组 ID 由机器人首次接入时自动写入，不用手填</td><td>有配置权限的运营</td></tr><tr><td>优盾配置</td><td>优盾充提通道的网关地址、商户号、商户密钥与回调地址</td><td><strong>仅超级管理员</strong></td></tr><tr><td>支付网关</td><td><strong>二选一</strong>：当前对用户生效的入金通道是「优盾」还是「TokenPay」</td><td><strong>仅超级管理员</strong></td></tr><tr><td>TokenPay 配置</td><td>TokenPay 通道的服务地址、ApiToken、回调地址与启用开关，详见<a href="/CoinExchange/zh/guide/finance">充值与提现</a></td><td><strong>仅超级管理员</strong></td></tr><tr><td>在线客服</td><td>客服机器人 Token、客服群组 ID、回调地址与密钥，详见<a href="/CoinExchange/zh/guide/customer-service">在线客服</a></td><td>有配置权限的运营</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">两个 Telegram 机器人不能共用</p><p>「TG 机器人」（告警）与「在线客服」（客服）<strong>必须是两个不同的机器人</strong>。共用一个 Token 会让两边互相抢消息、都收不全。</p></div><div class="tip custom-block"><p class="custom-block-title">密钥不回显</p><p>密码、密钥类字段保存后页面不会再显示原值（只显示已设置）。改动前请先在别处留好备份，否则填错只能重新向服务商索取。</p></div><div class="danger custom-block"><p class="custom-block-title">切换支付网关前</p><p>先确认目标通道的卡片<strong>已填写并启用</strong>，再切「支付网关」。切到一个没配好的通道，用户端的充值会立刻失败。</p></div>',49)])])}const u=a(r,[["render",s]]);export{g as __pageData,u as default};
